// The schema intermediate representation. defineSchema's builders produce this
// plain, serializable shape; the gateway compiles it into per-app DDL and the
// access-metadata the query engine enforces. Nothing here is executable — it is
// data the platform reads.
export const ROLES = ['owner', 'admin', 'writer', 'reader'];
// Higher rank = more authority. Used for "at least <role>" checks.
export const ROLE_RANK = { reader: 0, writer: 1, admin: 2, owner: 3 };
export function isViaRule(spec) {
    return typeof spec === 'object' && !Array.isArray(spec);
}
